#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 14a: Admin dashboard (sign in and Overview)
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part:
#   * a new app in dashboard/ (Next 14.2.35, its own Vercel project) for
#     dashboard.vidzmind.xyz, laid out like Atlassian Administration
#   * admins sign in with email and password, then a code from an
#     authenticator app (required), or a one time recovery code
#   * nobody can sign up: while no admin exists, the setup link is emailed
#     through Resend to ADMIN_EMAIL only
#   * Forgot password by email (the link expires in 30 minutes and a code is
#     still needed); emails on lockout, password change, recovery code use
#   * passwords as scrypt hashes, at least 15 characters; 5 failures lock the
#     account for 15 minutes; authenticator secrets encrypted with ADMIN_KEY
#   * the session is an httpOnly, Secure, SameSite=Strict cookie; it ends after
#     2 hours idle or 12 hours in all; every admin action goes to an audit log
#   * Overview: wallets, sign ins, videos, storage, views, live, this month's
#     usage, what needs attention, health, recent admin activity
#   * the Privacy Policy names Resend (admin email only), effective 15 October 2026
#
#   BACKEND    4 new files, 3 changed. Migration 019_admin (runs by itself)
#   DASHBOARD  24 new files (a new app; its packages install on Vercel)
#   FRONTEND   2 changed. No packages
#
#   ./vm_admin.sh            apply (needs Part 13b on the branch)
#   ./vm_admin.sh --force    apply even if local files differ from GitHub
#   ./vm_admin.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_admin"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_admin_backups"

ADD=(
  "backend/src/lib/admin.ts"
  "backend/src/lib/mail.ts"
  "backend/src/lib/adminOverview.ts"
  "backend/src/routes/admin.ts"
  "dashboard/package.json"
  "dashboard/package-lock.json"
  "dashboard/next.config.mjs"
  "dashboard/next-env.d.ts"
  "dashboard/tsconfig.json"
  "dashboard/tailwind.config.ts"
  "dashboard/postcss.config.js"
  "dashboard/.env.example"
  "dashboard/public/robots.txt"
  "dashboard/public/icon.svg"
  "dashboard/src/app/globals.css"
  "dashboard/src/app/layout.tsx"
  "dashboard/src/app/login/page.tsx"
  "dashboard/src/app/setup/page.tsx"
  "dashboard/src/app/forgot/page.tsx"
  "dashboard/src/app/reset/page.tsx"
  "dashboard/src/app/(admin)/layout.tsx"
  "dashboard/src/app/(admin)/page.tsx"
  "dashboard/src/components/AuthCard.tsx"
  "dashboard/src/components/QrCode.tsx"
  "dashboard/src/components/PasswordFields.tsx"
  "dashboard/src/components/Shell.tsx"
  "dashboard/src/lib/api.ts"
  "dashboard/src/lib/qr.ts"
