verify "$TMPD/a27" "${NEW_ADD[27]}" "dashboard/src/lib/qr.ts"

grep -q "$MARKER" "$TMPD/a0"                                   || die "admin.ts payload missing marker. Aborting."
grep -q 'export async function signInCode' "$TMPD/a0"            || die "admin.ts payload is wrong. Aborting."
grep -q 'api.resend.com/emails' "$TMPD/a1"                       || die "mail.ts payload is wrong. Aborting."
grep -q 'export async function overview' "$TMPD/a2"              || die "adminOverview.ts payload is wrong. Aborting."
grep -q 'SameSite=Strict' "$TMPD/a3"                             || die "routes/admin.ts payload is wrong. Aborting."
grep -q '"next": "14.2.35"' "$TMPD/a4"                  || die "dashboard package.json payload is wrong. Aborting."
grep -q 'Finish setup' "$TMPD/a17"              || die "dashboard setup page payload is wrong. Aborting."
grep -q 'Two step verification' "$TMPD/a16"     || die "dashboard sign in page payload is wrong. Aborting."
grep -q 'adminRouter' "$TMPD/m0"                         || die "index.ts payload missing admin. Aborting."
grep -q 'analyticsRouter' "$TMPD/m0"                     || die "index.ts payload lost analytics. Aborting."
grep -q '019_admin' "$TMPD/m1"                  || die "migrations.ts payload missing 019. Aborting."
grep -q '018_views' "$TMPD/m1"                  || die "migrations.ts payload lost 018. Aborting."
grep -q 'ADMIN_KEY' "$TMPD/m2"                           || die ".env.example payload is wrong. Aborting."
grep -q 'Resend' "$TMPD/m3"           || die "privacy page payload is wrong. Aborting."
grep -q '15 October 2026' "$TMPD/m4" || die "LegalPage.tsx payload is wrong. Aborting."
say "33 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied the admin dashboard (Part 14a)."
say "Migration 019_admin runs when the backend starts. The dashboard installs its own packages."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "  (cd dashboard && npm install && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_admin.sh --revert"
